// Production: use n8n Execute Command node
// nmap -sn 10.0.0.0/24 -oJ /tmp/hosts.json && nmap -sV --open -T3 -iL /tmp/hosts.txt -oJ /tmp/ports.json
// Mock structure — replace with actual nmap JSON parsing
const baseline=$input.all().map(i=>i.json);
const current=[{ip:'10.0.1.10',hostname:'prod-web-01',ports:[{port:443,service:'https'},{port:80,service:'http'}]},
               {ip:'10.0.1.20',hostname:'prod-db-01',ports:[{port:5432,service:'postgres'},{port:22,service:'ssh'}]}];
const baselineMap={};
baseline.forEach(h=>{baselineMap[h.ip_address]=JSON.parse(h.open_ports_json||'[]');});
const changes=[];
for(const host of current){
  const prevPorts=(baselineMap[host.ip]||[]).map(p=>p.port);
  const currPorts=host.ports.map(p=>p.port);
  const newPorts=currPorts.filter(p=>!prevPorts.includes(p));
  if(newPorts.length>0)changes.push({ip:host.ip,hostname:host.hostname,type:'NEW_PORT',detail:`New ports: ${newPorts.join(', ')}`,severity:'High'});
}
return[{json:{hosts_scanned:current.length,changes,change_count:changes.length,scanned_at:new Date().toISOString()}}];

